const targets = [
  /^Under \$25,000/,
  /^Under 30,000 miles/,
  /^Apple CarPlay/,
  /^Adaptive Cruise Control/,
  /^Blindspot Sensors/,
];
const log = [];
for (const re of targets) {
  let obs = phi.observe({ maxElements: 300 });
  let node = obs.nodes.find(n => re.test(n.name || ""));
  if (!node) { log.push({ filter: String(re), found: false }); continue; }
  const r = phi.click(node.ref);
  log.push({ filter: String(re), clicked: node.name, url: r.url, changed: r.changed ? Object.keys(r.changed) : null });
  phi.sleep(1500);
}
phi.waitForNetworkIdle({ idleMs: 1000, timeoutMs: 20000 });
phi.sleep(1000);
return { log, url: phi.tabs.list().length, text: phi.text().slice(0, 1500) };

