const cards = phi.js(() => {
  const anchors = Array.from(document.querySelectorAll("a[href*='/vehicle/']"));
  const out = [];
  const seen = new Set();
  for (const a of anchors) {
    const id = a.getAttribute('href');
    if (seen.has(id)) continue;
    // find enclosing card container text
    let el = a;
    for (let i = 0; i < 8 && el; i++) { el = el.parentElement; if (el && /Honda Civic/.test(el.innerText || "") && el.innerText.length > 60) break; }
    seen.add(id);
    out.push({ href: id, text: (el ? el.innerText : a.innerText).replace(/\n+/g, " | ").slice(0, 200) });
  }
  return out.slice(0, 16);
});
return cards;

